import re


def parse_log(baris):
    kv = dict(re.findall(r'(\w+)=(\S+)', baris))
    return {'endpoint': kv['endpoint'], 'status': int(kv['status']), 'durasi_ms': int(kv['durasi_ms'])}


def muat(baris_log):
    hasil = []
    for baris in baris_log:
        try:
            hasil.append(parse_log(baris))
        except (KeyError, ValueError):
            pass
    return hasil


def ketersediaan(entri):
    if not entri:
        return 1.0
    return round(sum(1 for e in entri if e['status'] < 500) / len(entri), 4)


def p95_per_endpoint(entri):
    per = {}
    for e in entri:
        per.setdefault(e['endpoint'], []).append(e['durasi_ms'])
    return {k: persentil(v, 95) for k, v in per.items()}


def _gagal(entri):
    return sum(1 for e in entri if e['status'] >= 500)


def sisa_budget(entri, slo):
    budget = len(entri) * (1 - slo)
    if budget <= 0:
        return 0.0
    return max(0.0, round((budget - _gagal(entri)) / budget, 4))


def status_alert(entri, slo):
    if not entri:
        return 'ok'
    burn = round((_gagal(entri) / len(entri)) / (1 - slo), 2)
    if burn >= 10:
        return 'page'
    if burn >= 2:
        return 'tiket'
    return 'ok'

