solution.code:
def laju_per_detik(sampel):
    if len(sampel) < 2:
        return 0.0
    tambah = 0
    for (_, a), (_, b) in zip(sampel, sampel[1:]):
        tambah += b - a if b >= a else b
    return tambah / (sampel[-1][0] - sampel[0][0])

