def hitung_red(permintaan, jendela_detik):
    n = len(permintaan)
    if n == 0:
        return {'rate': 0.0, 'error': 0.0, 'p95': 0}
    gagal = sum(1 for p in permintaan if p['status'] >= 500)
    return {
        'rate': n / jendela_detik,
        'error': gagal / n,
        'p95': persentil([p['durasi_ms'] for p in permintaan], 95),
    }

