solution.code:
def alert_aktif(nilai, naik, turun, min_berturut):
    aktif = False
    hitung = 0
    hasil = []
    for v in nilai:
        if aktif:
            if v < turun:
                aktif = False
                hitung = 0
        else:
            hitung = hitung + 1 if v > naik else 0
            if hitung >= min_berturut:
                aktif = True
        hasil.append(aktif)
    return hasil

