solution.code:
def mttd_mttr(insiden):
    if not insiden:
        return (0.0, 0.0)
    n = len(insiden)
    mttd = sum(i['deteksi'] - i['mulai'] for i in insiden) / n
    mttr = sum(i['pulih'] - i['mulai'] for i in insiden) / n
    return (round(mttd, 1), round(mttr, 1))
